#include <utility>
template<class E, class F> bool dpx_rejects(F&& action) {
  try { std::forward<F>(action)(); }
  catch (const E&) { return true; }
  return false;
}

int main() {
std::cout << std::boolalpha << ([]{
  Feed f;
  auto a=std::make_shared<Total>();
  bool denied=false;
  f.subscribe(a);
  a->after=[&]{
    denied=dpx_rejects<std::logic_error>([&]{
      f.unsubscribe(a);
    });
  };
  f.publish(1);
  return denied;
})() << '\n';
}

